"""Slice print-forge models with the OrcaSlicer command line to make real test fixtures.

This is what the ``real-fixtures`` CI workflow runs; it is not needed to run the tests. It

1. writes the models with print-forge (pinned by the workflow),
2. resolves each OrcaSlicer system profile's ``inherits`` chain into one flat JSON file (the
   command line does not resolve inheritance for filament profiles, and a machine profile
   with an unresolved parent fails), keeping ``"from": "system"``,
3. slices every fixture in :data:`FIXTURES` and writes ``<name>.gcode.3mf``, and
4. writes ``provenance.json``: OrcaSlicer version, download URL and SHA-256, profile names,
   profile bundle version, the exact command lines, and the date in the G-code header.

``--check DIR`` instead compares freshly sliced files in DIR with the committed fixtures,
ignoring the one header line that carries the slicing date and time.

Standard library only. Usage (see ``.github/workflows/real-fixtures.yml``)::

    python tests/fixtures/real/slice_fixtures.py --orca squashfs-root/AppRun \\
        --profiles squashfs-root/resources/profiles/BBL --out out \\
        --orca-url URL --orca-sha256 HEX
    python tests/fixtures/real/slice_fixtures.py --check out
"""

from __future__ import annotations

import argparse
import hashlib
import json
import re
import shlex
import subprocess
import sys
import tempfile
import zipfile
from dataclasses import dataclass
from pathlib import Path

HERE = Path(__file__).resolve().parent

#: print-forge commands for the models, run as ``python -m print_forge <args> --out <file>``.
MODELS: dict[str, list[str]] = {
    "bead-gem-12.stl": ["bead", "--preset", "gem-12"],
    "tile-7.stl": ["letter", "--preset", "tile-7", "--ascii"],
}


@dataclass(frozen=True)
class Fixture:
    name: str
    machine: str
    process: str
    #: (filament profile, colour written into the profile as ``filament_colour``)
    filaments: tuple[tuple[str, str], ...]
    models: tuple[str, ...]
    #: 1-based filament per model, or ``None`` for the first filament everywhere.
    filament_ids: tuple[int, ...] | None = None


#: The default 0.4 mm nozzle, process and filament profile of each printer in OrcaSlicer.
FIXTURES = (
    Fixture(
        "p1s-bead",
        "Bambu Lab P1S 0.4 nozzle",
        "0.20mm Standard @BBL X1C",
        (("Bambu PLA Basic @BBL X1C", "#FFFFFF"),),
        ("bead-gem-12.stl",),
    ),
    Fixture(
        "a1-bead",
        "Bambu Lab A1 0.4 nozzle",
        "0.20mm Standard @BBL A1",
        (("Bambu PLA Basic @BBL A1", "#FFFFFF"),),
        ("bead-gem-12.stl",),
    ),
    Fixture(
        "a1-mini-bead",
        "Bambu Lab A1 mini 0.4 nozzle",
        "0.20mm Standard @BBL A1M",
        (("Bambu PLA Basic @BBL A1M", "#FFFFFF"),),
        ("bead-gem-12.stl",),
    ),
    Fixture(
        "p1s-two-colour",
        "Bambu Lab P1S 0.4 nozzle",
        "0.20mm Standard @BBL X1C",
        (("Bambu PLA Basic @BBL X1C", "#FFFFFF"), ("Bambu PLA Matte @BBL X1C", "#161616")),
        ("bead-gem-12.stl", "tile-7.stl"),
        (1, 2),
    ),
)

_GENERATED = re.compile(rb"^; generated by (\S+) (\S+) on (\S+) at (\S+)$", re.MULTILINE)


def index_profiles(vendor_dir: Path) -> dict[str, Path]:
    """Map each profile's ``name`` to its file."""
    found: dict[str, Path] = {}
    for path in sorted(vendor_dir.rglob("*.json")):
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if isinstance(data, dict) and isinstance(data.get("name"), str):
            found.setdefault(data["name"], path)
    return found


def flatten(name: str, names: dict[str, Path]) -> dict[str, object]:
    """Merge a profile with its ``inherits`` chain, child keys winning."""
    chain: list[dict[str, object]] = []
    current: object = name
    while isinstance(current, str) and current:
        if current not in names:
            raise SystemExit(f"profile {current!r} (inherited by {name!r}) not found")
        data = json.loads(names[current].read_text(encoding="utf-8"))
        chain.append(data)
        current = data.get("inherits")
    merged: dict[str, object] = {}
    for data in reversed(chain):
        merged.update(data)
    merged.pop("inherits", None)
    merged["name"] = name
    merged["from"] = "system"
    return merged


def make_models(work: Path) -> dict[str, str]:
    commands = {}
    for filename, args in MODELS.items():
        command = [sys.executable, "-m", "print_forge", *args, "--out", str(work / filename)]
        subprocess.run(command, check=True, stdout=subprocess.DEVNULL)
        commands[filename] = shlex.join(["print-forge", *args, "--out", filename])
    return commands


def slice_one(
    orca: Path, fixture: Fixture, names: dict[str, Path], work: Path, out: Path
) -> dict[str, object]:
    profiles = work / fixture.name
    profiles.mkdir()
    settings = []
    for kind, profile in (("machine", fixture.machine), ("process", fixture.process)):
        path = profiles / f"{kind}.json"
        path.write_text(json.dumps(flatten(profile, names), indent=1), encoding="utf-8")
        settings.append(path)
    filaments = []
    for number, (profile, colour) in enumerate(fixture.filaments, start=1):
        data = flatten(profile, names)
        data["filament_colour"] = [colour]
        path = profiles / f"filament{number}.json"
        path.write_text(json.dumps(data, indent=1), encoding="utf-8")
        filaments.append(path)
    slicer_out = work / f"{fixture.name}-out"
    slicer_out.mkdir()
    target = f"{fixture.name}.gcode.3mf"
    args = [
        "--datadir",
        str(work / "datadir"),
        "--slice",
        "0",
        "--load-settings",
        ";".join(str(p) for p in settings),
        "--load-filaments",
        ";".join(str(p) for p in filaments),
    ]
    if fixture.filament_ids is not None:
        args += ["--load-filament-ids", ",".join(str(i) for i in fixture.filament_ids)]
    args += ["--arrange", "1", "--outputdir", str(slicer_out), "--export-3mf", target]
    args += [str(work / model) for model in fixture.models]
    result = subprocess.run([str(orca), *args], capture_output=True, text=True, check=False)
    produced = slicer_out / target
    if result.returncode != 0 or not produced.is_file():
        print(result.stdout[-4000:], result.stderr[-4000:], sep="\n", file=sys.stderr)
        raise SystemExit(f"{fixture.name}: OrcaSlicer exited with {result.returncode}")
    blob = produced.read_bytes()
    (out / target).write_bytes(blob)
    with zipfile.ZipFile(produced) as archive:
        gcode = archive.read("Metadata/plate_1.gcode")
    header = _GENERATED.search(gcode)
    if header is None:
        raise SystemExit(f"{fixture.name}: no '; generated by' header in the G-code")
    shown = ["orca-slicer", *(a.replace(str(work), "$WORK").replace("\\", "/") for a in args)]
    return {
        "file": target,
        "sha256": hashlib.sha256(blob).hexdigest(),
        "slicer": header.group(1).decode(),
        "slicer_version": header.group(2).decode(),
        "sliced_at": f"{header.group(3).decode()} {header.group(4).decode()}",
        "machine_profile": fixture.machine,
        "process_profile": fixture.process,
        "filament_profiles": [profile for profile, _ in fixture.filaments],
        "filament_colours": [colour for _, colour in fixture.filaments],
        "models": list(fixture.models),
        "filament_ids": list(fixture.filament_ids) if fixture.filament_ids else None,
        "command": shlex.join(shown),
    }


def generate(args: argparse.Namespace) -> None:
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    vendor = Path(args.profiles)
    bundle = json.loads((vendor.parent / "BBL.json").read_text(encoding="utf-8"))
    names = index_profiles(vendor)
    with tempfile.TemporaryDirectory(dir=args.tmp) as tmp:
        work = Path(tmp)
        model_commands = make_models(work)
        fixtures = [slice_one(Path(args.orca), f, names, work, out) for f in FIXTURES]
    provenance = {
        "about": "Real OrcaSlicer output, made by tests/fixtures/real/slice_fixtures.py in the "
        "real-fixtures CI workflow. Nothing in these files was edited by hand.",
        "orca_slicer": {
            "download": args.orca_url,
            "sha256": args.orca_sha256,
            "licence": "AGPL-3.0 (https://github.com/SoftFever/OrcaSlicer)",
            "profile_bundle": f"BBL {bundle.get('version')}",
        },
        "print_forge": {"version": args.print_forge, "commands": model_commands},
        "runner": args.runner,
        "fixtures": fixtures,
    }
    (out / "provenance.json").write_text(json.dumps(provenance, indent=2) + "\n", "utf-8")
    print(json.dumps(provenance, indent=2))


def _plate_gcode(path: Path) -> bytes:
    with zipfile.ZipFile(path) as archive:
        gcode = archive.read("Metadata/plate_1.gcode")
    return _GENERATED.sub(b"; generated by <date removed>", gcode)


def check(fresh_dir: Path) -> int:
    failures = 0
    for fixture in FIXTURES:
        name = f"{fixture.name}.gcode.3mf"
        committed, fresh = HERE / name, fresh_dir / name
        same = _plate_gcode(committed) == _plate_gcode(fresh)
        print(f"{name}: {'identical apart from the date line' if same else 'DIFFERENT'}")
        failures += not same
    return 1 if failures else 0


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--check", metavar="DIR", help="compare DIR with the committed files")
    parser.add_argument("--orca", help="OrcaSlicer executable")
    parser.add_argument("--profiles", help="OrcaSlicer resources/profiles/BBL directory")
    parser.add_argument("--out", help="directory for the .gcode.3mf files and provenance")
    parser.add_argument("--orca-url", default="", help="where the OrcaSlicer build came from")
    parser.add_argument("--orca-sha256", default="", help="SHA-256 of that download")
    parser.add_argument("--print-forge", default="", help="print-forge version used")
    parser.add_argument("--runner", default="", help="CI runner image, for the record")
    parser.add_argument("--tmp", default=None, help="parent directory for temporary files")
    args = parser.parse_args()
    if args.check:
        return check(Path(args.check))
    if not (args.orca and args.profiles and args.out):
        parser.error("--orca, --profiles and --out are required unless --check is given")
    generate(args)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
